class METDebugSOExtract extends RunBase
{
    DialogField salesIdField;
    SalesId salesId;

}

Method.Source:
public Object dialog()
{
    Dialog dialog = super();

    dialog.caption("Select SO to extract");
    salesIdField = dialog.addField(extendedTypeStr(SalesId));
    return dialog;
}

public boolean getFromDialog()
{
    salesId = salesIdField.value();
    return super();
}

public void run()
{
    if (salesId)
    {
        ttsbegin;
        METSalesPickingListGenerationTaskContract   dataContract    = new METSalesPickingListGenerationTaskContract();
        METSalesPickingListGenerationTaskService    service         = new METSalesPickingListGenerationTaskService();

        dataContract.parmSalesId(salesId);

        service.process(dataContract);
        ttscommit;
    }
}

/// <summary>
/// Class entry point. The system will call this method when a designated menu
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    METDebugSOExtract debugSOExtract = new METDebugSOExtract();

    if (debugSOExtract.prompt())
    {
        debugSOExtract.run();
    }
}
